/**
 * Brand assets + theme detection for the browser half.
 *
 * The SVGs are the marketplace logo in its light and dark variants (same
 * sources as dsh-plugins-mp.com/apps/web/public), embedded as base64 data
 * URIs — the client bundle is a single self-contained CJS closure with no
 * asset serving, so file URLs are not an option.
 *
 * Dark theme detection mirrors DSH itself: the web app marks its theme with
 * the empty attribute data-ds-dark-theme on <body> (see body[data-ds-dark-theme]
 * rules in the DSH stylesheet). One shared MutationObserver fans out to all
 * subscribers, so the tab-strip icon, the + new-tab menu icon and the header
 * logo re-render on theme flips without per-instance observers.
 */
import { useEffect, useState } from 'react'
import type { ReactNode } from 'react'

const LOGO_LIGHT = 'data:image/svg+xml;base64,'
const LOGO_DARK = 'data:image/svg+xml;base64,'

function bodyDark(): boolean {
  return typeof document !== 'undefined' && document.body?.hasAttribute('data-ds-dark-theme') === true
}

let darkSubscribers: Set<() => void> | null = null

function watchDarkTheme(cb: () => void): () => void {
  if (typeof document === 'undefined') return () => {}
  if (darkSubscribers === null) {
    darkSubscribers = new Set()
    new MutationObserver(() => {
      for (const fn of darkSubscribers!) fn()
    }).observe(document.body, { attributes: true, attributeFilter: ['data-ds-dark-theme'] })
  }
  darkSubscribers.add(cb)
  return () => {
    darkSubscribers!.delete(cb)
  }
}

export function useDarkTheme(): boolean {
  const [dark, setDark] = useState(bodyDark)
  useEffect(() => {
    const sync = (): void => setDark(bodyDark())
    sync()
    return watchDarkTheme(sync)
  }, [])
  return dark
}

/** The marketplace mark at the given pixel size, in the theme-aware variant. */
export function BrandMark(props: { size: number }): ReactNode {
  const dark = useDarkTheme()
  return (
    <img
      src={dark ? LOGO_DARK : LOGO_LIGHT}
      width={props.size}
      height={props.size}
      alt=""
      aria-hidden="true"
      style={{
        width: props.size,
        height: props.size,
        display: 'inline-block',
        verticalAlign: 'middle',
        flex: '0 0 auto',
      }}
    />
  )
}
